static connection *connCreateAcceptedUnix(struct aeEventLoop *el, int fd, void *priv) {
    UNUSED(priv);
    connection *conn = connCreateUnix(el);
    conn->fd = fd;
    conn->state = CONN_STATE_ACCEPTING;
    return conn;
